import React, { useState } from 'react';
import './UserText.css';
import axios from 'axios';

const UserText = () => {
  const [text, setText] = useState('');

  const handleClick = (char) => {
    setText(prev => prev + char);
  };

  const handleSubmit = async () => {
    if (text) {
      try {
        const response = await axios.post('http://localhost:8080/api/text', { text });
        console.log('Text sent successfully:', response.data);
        setText('');
      } catch (error) {
        console.error('Error sending text:', error);
      }
    }
  };

  const handleReset = () => {
    setText('');
  };

  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const numbers = '0123456789'.split('');

  return (
    <div className="section4-wrapper">
      <div className="text-display">{text || 'Text'}</div>

      <div className="button-group">
        <button className="action-button" onClick={handleSubmit}>Submit</button>
        <button className="action-button" onClick={handleReset}>Reset</button>
      </div>

      <div className="keyboard-split-container">
        <div className="keyboard-grid left">
          {uppercase.map(char => (
            <button key={char} className="letter-button" onClick={() => handleClick(char)}>
              {char}
            </button>
          ))}
        </div>
        <div className="keyboard-grid right">
          {numbers.map(num => (
            <button key={num} className="letter-button" onClick={() => handleClick(num)}>
              {num}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default UserText;
